// Literal port of the team's Casa3DSDK (module interaction/doors). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installInteractionDoors(K: Kernel, shared: Shared): void {
  const { t, colliderChanged, invalidateShadow, applyPiece, hudMessage } = K;
  // ---------- doors: turning handle, lock and phased movement ----------
  function linkDoorLeaves() { // called after assembleInteractive: wires the handles to the leaf
    for (const fo of shared.ctx.leaves) fo.handles = (fo.handleNames || []).map(n => shared.inter.defs.get(n)).filter(Boolean);
  }
  function handleApply(fo) { for (const mc of fo.handles || []) { mc.t = fo.hT || 0; applyPiece(mc); } }
  function toggleDoor(fo) {
    if (fo.phase === 'rattle') return;
    if (fo.phase === 'handle' || fo.phase === 'swing') { fo.open = !fo.open; shared.doorState.set(fo.id, fo.open); fo.col.off = fo.open; colliderChanged(fo.col); fo.anim = true; fo.phase = 'swing'; return; } // reverses in the middle of the movement
    if (fo.blockedFlag || fo.locked) { fo.phase = 'rattle'; fo.jig = 0.7; shared.ctx.animateDoorsOn = true; hudMessage(t(fo.blockedFlag ? 'message.boarded' : 'message.locked')); return; }
    fo.open = !fo.open; shared.doorState.set(fo.id, fo.open); fo.col.off = fo.open; colliderChanged(fo.col); fo.anim = true; shared.ctx.animateDoorsOn = true;
    if (fo.handles && fo.handles.length) { fo.phase = 'handle'; fo.hT = fo.hT || 0; } else fo.phase = 'swing';
  }
  function animateDoors(dt) {
    if (!shared.ctx.animateDoorsOn) return; let active = false;
    for (const fo of shared.ctx.leaves) {
      if (!fo.phase) continue; active = true;
      if (fo.phase === 'handle') { fo.hT = Math.min(1, (fo.hT || 0) + dt / 0.16); handleApply(fo); if (fo.hT >= 1) fo.phase = 'swing'; }
      else if (fo.phase === 'swing') {
        const target = fo.open ? 1 : 0, d = target - fo.t, step = dt / 0.35; fo.t = Math.abs(d) <= step ? target : fo.t + Math.sign(d) * step; applyLeaf(fo);
        if (fo.t === target) { fo.anim = false; fo.phase = (fo.handles && fo.handles.length) ? 'rise' : null; }
      } else if (fo.phase === 'rise') { fo.hT = Math.max(0, fo.hT - dt / 0.2); handleApply(fo); if (fo.hT <= 0) fo.phase = null; }
      else if (fo.phase === 'rattle') { fo.jig -= dt; fo.hT = fo.jig > 0 ? 0.55 * Math.abs(Math.sin(fo.jig * 26)) : 0; handleApply(fo); if (fo.jig <= 0) { fo.hT = 0; handleApply(fo); fo.phase = null; } }
    }
    shared.ctx.animateDoorsOn = active; invalidateShadow();
  }
  function wallBlocks(ex, ez, ax, az, floor) { // does the eye->target segment cut a wall?
    const n = shared.ctx.wallColliders != null ? shared.ctx.wallColliders : 0;
    for (let i = 0; i < n; i++) {
      const c = shared.ctx.colliders[i]; if (c.f !== floor && !(c.f === -1 && floor === 0)) continue;
      let t0 = 0, t1 = 1; const dx = ax - ex, dz = az - ez;
      for (const [p, d, lo, hi] of [[ex, dx, c.x0 + 0.01, c.x1 - 0.01], [ez, dz, c.z0 + 0.01, c.z1 - 0.01]]) {
        if (Math.abs(d) < 1e-9) { if (p < lo || p > hi) { t0 = 2; break; } } else { let a = (lo - p) / d, b = (hi - p) / d; if (a > b) [a, b] = [b, a]; t0 = Math.max(t0, a); t1 = Math.min(t1, b); if (t0 > t1) break; }
      }
      if (t0 <= t1) return true;
    }
    return false;
  }
  const doorText = fo => (fo.blockedFlag || fo.locked ? t('prompt.lockedDoor') : t(fo.open ? 'prompt.close' : 'prompt.open', { what: t('what.door') }));
  function applyLeaf(fo) {
    for (const g of fo.gs) { if (fo.type === 'steel') g.scale.y = 1 - fo.t * (1 - fo.minScale); else g.rotation.y = fo.t * fo.rot; g.updateMatrix(); }
  }
  Object.assign(K, { linkDoorLeaves, handleApply, toggleDoor, animateDoors, wallBlocks, doorText, applyLeaf });
}
